// Some portions generated by Claude

/** A scrolled list's position and the empty room it keeps above and below its content, in pixels. */
export type ScrollRoom = { top: number; bottom: number; scrollTop: number };

/**
 * Where a list must scroll, and how much empty room it needs above and below its content, to put an element that moved
 * `drift` pixels down on screen back where it was. Room above is used when the list cannot scroll up far enough, room
 * below when the content is too short for the scroll position; both are only as large as needed, so with a drift of 0
 * this gives up the room the user has scrolled off screen without moving anything that is on screen.
 *
 * @param content the content's height without the room
 * @param viewport the list's visible height
 */
export function settleScroll(current: ScrollRoom, content: number, viewport: number, drift: number): ScrollRoom {
  // Where the content starts relative to the top of the list's visible area must move up by drift.
  const offset = current.top - current.scrollTop - drift;
  const top = Math.max(0, offset);
  const scrollTop = Math.max(0, -offset);
  return {
    top,
    bottom: Math.max(0, scrollTop + viewport - top - content),
    scrollTop,
  };
}

/** What a click in the list holds in place: a filter's heading, a value, a range, or a "more" button. */
const HELD = "summary, .facet-value, .facet-range, .filter-more";
/** Clicks here change what is above the list (chips, the match count): the list itself stays put. */
const ABOVE = ".filter-chips button, .filter-sidebar-header button";
const SCROLL_KEYS = new Set(["ArrowUp", "ArrowDown", "PageUp", "PageDown", "Home", "End"]);
/** Focus this soon after a pointer press comes from that press, not from the keyboard. */
const POINTER_FOCUS_MS = 600;

/**
 * Keeps what was last clicked in a scrolling panel where it was on screen while the panel changes around it: a filter
 * opening or closing, chips appearing above the list, values elsewhere coming and going, the list getting shorter than
 * its scroll position. The hold ends when the user scrolls, moves focus with the keyboard, or leaves the panel.
 *
 * The list's CSS reserves the room through `--hold-top` and `--hold-bottom`; `content` is the element inside the list
 * that holds everything else. Call `settle()` after every render of the panel, before the browser paints.
 */
export function holdClickedPlace(panel: HTMLElement, list: HTMLElement, content: HTMLElement) {
  let held: { element: Element; at: number } | undefined;
  let room = { top: 0, bottom: 0 };
  let pressedAt = -Infinity;
  // The list as the last settle left it: a scroll that changes only its position was not caused by the panel.
  let seen = { scrollTop: 0, content: 0, viewport: 0 };

  const setRoom = (top: number, bottom: number) => {
    if (top !== room.top) list.style.setProperty("--hold-top", `${top}px`);
    if (bottom !== room.bottom) list.style.setProperty("--hold-bottom", `${bottom}px`);
    room = { top, bottom };
  };

  const settle = () => {
    if (held && !held.element.isConnected) release();
    const height = content.getBoundingClientRect().height;
    if (held || room.top || room.bottom) {
      const moved = held ? held.element.getBoundingClientRect().top - held.at : 0;
      const next = settleScroll(
        { ...room, scrollTop: list.scrollTop },
        height,
        list.clientHeight,
        Math.abs(moved) < 0.5 ? 0 : moved,
      );
      // The room first, so that the list can scroll as far as it has to.
      setRoom(next.top, next.bottom);
      if (Math.abs(list.scrollTop - next.scrollTop) >= 0.5) list.scrollTop = next.scrollTop;
    }
    look(height);
  };

  const look = (height = content.getBoundingClientRect().height) => {
    seen = { scrollTop: list.scrollTop, content: height, viewport: list.clientHeight };
  };

  const hold = (element: Element | null | undefined) => {
    held = element ? { element, at: element.getBoundingClientRect().top } : undefined;
    // A scroll from before the hold, whose event is still to come, must not end it.
    if (held) look();
    // The browser's own scroll anchoring would pick another element and fight this one.
    list.style.overflowAnchor = held ? "none" : "";
  };

  const release = () => hold(undefined);

  /** The first heading or value at least partly in view. */
  const firstShown = () => {
    const top = list.getBoundingClientRect().top;
    for (const element of content.querySelectorAll("summary, .facet-value")) {
      if (element.getBoundingClientRect().bottom > top) return element;
    }
    return undefined;
  };

  const holdTarget = (target: EventTarget | null) => {
    if (!(target instanceof Element)) return release();
    const inside = target.closest(HELD);
    if (inside && list.contains(inside)) return hold(inside);
    hold(target.closest(ABOVE) && panel.contains(target) ? firstShown() : undefined);
  };

  const onPointerDown = (event: PointerEvent) => {
    pressedAt = performance.now();
    // A press on the scroll bar, or the middle button's autoscroll, scrolls the list.
    if (event.target === list || event.button === 1) return release();
    holdTarget(event.target);
  };
  const onClick = (event: MouseEvent) => holdTarget(event.target);
  const onInput = (event: Event) => {
    if (event.target instanceof Element && list.contains(event.target)) holdTarget(event.target);
  };
  const onKeyDown = (event: KeyboardEvent) => {
    const target = event.target;
    const typing =
      target instanceof HTMLElement && (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName));
    if (SCROLL_KEYS.has(event.key) && !typing) release();
  };
  // Focus moved with the keyboard scrolls the focused element into view.
  const onFocusIn = () => {
    if (performance.now() - pressedAt > POINTER_FOCUS_MS) release();
  };
  // Find in page or a script scrolled the list on purpose: the list did not change, only where it is scrolled to.
  const onScroll = () => {
    if (
      held &&
      Math.abs(list.scrollTop - seen.scrollTop) >= 1 &&
      content.getBoundingClientRect().height === seen.content &&
      list.clientHeight === seen.viewport
    ) {
      release();
    }
    settle();
  };
  // Room above the list is not left behind once the pointer is elsewhere.
  const onPointerLeave = (event: PointerEvent) => {
    if (event.pointerType !== "mouse") return;
    release();
    if (room.top) {
      setRoom(0, room.bottom);
      settle();
    }
  };

  const resized = typeof ResizeObserver === "undefined" ? undefined : new ResizeObserver(() => settle());
  resized?.observe(list);
  resized?.observe(content);
  const options = { capture: true };
  panel.addEventListener("pointerdown", onPointerDown, options);
  panel.addEventListener("click", onClick, options);
  panel.addEventListener("input", onInput, options);
  panel.addEventListener("keydown", onKeyDown, options);
  panel.addEventListener("focusin", onFocusIn, options);
  panel.addEventListener("pointerleave", onPointerLeave);
  list.addEventListener("wheel", release, { passive: true });
  list.addEventListener("touchstart", release, { passive: true });
  list.addEventListener("scroll", onScroll, { passive: true });

  return {
    settle,
    dispose() {
      resized?.disconnect();
      panel.removeEventListener("pointerdown", onPointerDown, options);
      panel.removeEventListener("click", onClick, options);
      panel.removeEventListener("input", onInput, options);
      panel.removeEventListener("keydown", onKeyDown, options);
      panel.removeEventListener("focusin", onFocusIn, options);
      panel.removeEventListener("pointerleave", onPointerLeave);
      list.removeEventListener("wheel", release);
      list.removeEventListener("touchstart", release);
      list.removeEventListener("scroll", onScroll);
    },
  };
}
